if js and js.kind==Zie[2157]and not(type(Xr.shred)==Zie[1987])then
local ps=tonumber(Xr.amp)
local qs=Hr and((type(Hr.ampTypes)==Zie[1987]and Hr.ampTypes[js.dtype])or(tonumber(Hr.amp)or 0)>0)
if ps and ps>0 and not qs then
