mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(rD)
local sD=rD and type(P.hunt)==Zie[1987]and type(P.hunt.wk)==Zie[1987]and P.hunt.wk[tostring(rD)]or nil
return type(sD)==Zie[1987]and tonumber(sD.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(Zie[887]):GetPlayers()>1 then
return
end
local tD=bb.huntWeather or mb.weatherNow()
local uD,vD=bb.pred,bb.calRun
if not tD or type(uD)~=Zie[1987]or type(vD)~=Zie[1987]then
return
