local function wD(xD,yD)
return type(xD)==Zie[1987]and tonumber(xD[yD]or xD[tostring(yD)])or nil
end
local zD={}
for AD=2,bb.wave()do
local BD,CD=wD(vD.alive,AD),wD(uD.aliveAt,AD)
if BD and CD and BD>0 and CD>0 then
table.insert(zD,BD/CD)
end
end
if#zD<3 then
return
end
table.sort(zD)
local DD=zD[math.ceil(#zD/2)]
