local GD=mb.weatherK(tD)
local HD=math.max(1,FD)
local JD=math.exp((HD*math.log(GD)+math.log(GD*DD))/(HD+1))
JD=U.clamp(JD,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(tD),old=ED}
P.hunt.wk[tostring(tD)]={k=JD,n=(type(ED)==Zie[1987]and tonumber(ED.n)or 0)+1,at=os.time()}
F.log(1,Zie[2527],string.format(Zie[2528],tostring(tD),DD,tostring(tD),JD,GD,P.hunt.wk[tostring(tD)].n))
end
function mb.cardGems(KD,LD)
