local gP,hP=pcall(W.needsHelp,fP)
if gP and hP then
return W.MATCHED_DAILY_P
end
end
local iP=fP.rec
local jP=fP.p0 or W.PRIOR_WIN[fP.kind]or 0.7
local kP=W.sim(fP)
if kP and not(kP.trust and not kP.trust.ok)then
local lP=kP.calibrated or iP.runs>0
local mP=(kP.trust and kP.trust.ok)and 6 or(lP and 3 or 1.5)
local nP=(lP or kP.hopeless)and 0 or 2
local oP,pP=pcall(gb.styleP,kP)
return(iP.wins+jP*nP+(oP and pP or kP.p)*mP)/(iP.runs+nP+mP)
end
return(iP.wins+jP*2)/(iP.runs+2)
