function kb.xpGuess(nbb)
local obb=nbb.level and N.Levels[nbb.level]
if not obb then
return 0
end
local pbb=math.min(9,tonumber(obb.story_world_rank)or tonumber(nbb.rank)or 9)
local qbb=tonumber(obb.story_level_rank)or 6
local rbb=(nbb.kind==Zie[2027]and 1.5 or 1)*(pbb>5 and 2 or 1)
local sbb=2.1564^(pbb-1)*(40+10*qbb)/rbb
if nbb.kind==Zie[2006]then
sbb=3*30*2.1564^(pbb-1)/rbb
end
local tbb=pbb>=9 and 0.3 or(pbb>=7 and 0.5 or 1)
return sbb*tbb*6
end
