function ab.evoEats(Idb,Jdb)
local Kdb=N.session()
local Ldb,Mdb=pcall(V.score,Kdb.collection:get_unit_by_uuid(Idb.uuid))
for Ndb,Odb in ipairs(Idb.eats or{})do
for Pdb,Qdb in ipairs(hb.copies(Odb.id,Odb.shiny,Idb.uuid))do
local Rdb=Kdb.collection:get_unit_by_uuid(Qdb.uuid)or Qdb
local Sdb,Tdb=pcall(V.score,Rdb)
if Jdb[Qdb.uuid]or V.trait(Rdb)or(Ldb and Sdb and Tdb>=Mdb)then
return string.format(Zie[3083],V.name(Odb.id))
end
end
end
end
ab.pickNote={}
function ab.pickDone(Udb,Vdb,Wdb,Xdb)
O[Udb]=false
pcall(function()
nb.UI[Udb].Set(false,true)
end)
ab.pickNote[Udb]=Wdb
F.log(1,Zie[2491],Vdb..Zie[2329]..Wdb)
if F.notify then
F.notify(Vdb,Wdb,Xdb or Zie[2906])
end
F.saveSoon()
end
function ab.focusNextUp()
if O.focusNext==Zie[908]or nb.focusNow()~=Zie[908]then
return
end
local Ydb=O.focusNext
local Zdb=N.session()
local _db,aeb
for beb,ceb in pairs(Zdb.profile_data.collection.owned_units)do
if ceb.unit_id==Ydb and(not _db or(tonumber(ceb.xp)or 0)>aeb)then
_db,aeb=beb,tonumber(ceb.xp)or 0
end
end
if not _db then
O.focusNext=Zie[908]
F.log(1,Zie[2491],Zie[3084]..V.name(Ydb)..Zie[3085])
return F.saveSoon()
end
O.focusDone=O.evolveUnit
F.log(1,Zie[2491],Zie[3086]..V.name(Ydb))
ab.setFocus(_db)
nb.focusSig=nil
if F.notify then
F.notify(Zie[3087],Zie[3088]..V.name(Ydb),Zie[2906])
end
end
function ab.evolveBuyPlan(deb)
if not(O.autoEvolve and deb and deb.pinned and not deb.ready and deb.uuid==O.evolveUnit)then
return nil
end
for eeb,feb in ipairs(deb.plans or{})do
if feb.eventShop and(tonumber(feb.cost)or 0)>0 and feb.currency and hb.have(feb.item)<(tonumber(feb.need)or 1)and(tonumber(N.cur(feb.currency))or 0)>=feb.cost then
return feb
end
end
return nil
end
function ab.evolveBuy(geb)
local heb=ab.evolveBuyPlan(geb)
if not heb or F.where~=Zie[2058]then
return false
end
if F.req.back.evobuy and U.now()<F.req.back.evobuy then
return false
end
local ieb=(N.Items[heb.item]or{}).name or heb.item
local jeb=hb.have(heb.item)
local keb,leb=F.request(Zie[3089],Zie[2596],heb.item,Zie[2004],Zie[2597],Zie[2428])
local meb=U.now()
while U.now()-meb<4 and hb.have(heb.item)<=jeb do
task.wait(0.25)
end
if hb.have(heb.item)>jeb then
cb.add(ieb,heb.cost,tostring(heb.currency),Zie[3090]..V.name(geb.from)..Zie[3091])
if F.notify then
F.notify(Zie[3087],Zie[2904]..ieb..Zie[3032]..V.name(geb.from),Zie[2906])
end
pcall(hb.refresh)
return true
end
F.log(1,Zie[2907],string.format(Zie[3092],ieb,tostring(keb and leb or Zie[2521])))
F.backoff(Zie[3089],900)
return false
end
function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==Zie[908]then
return
end
local neb=N.session()
if not(neb and neb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(Zie[3093],Zie[3087],Zie[3094],Zie[3095])
end
local oeb
for peb,qeb in ipairs(P.goals or{})do
if qeb.pinned and qeb.uuid==O.evolveUnit then
oeb=qeb
break
end
end
if not oeb then
local reb=neb.collection:get_unit_by_uuid(O.evolveUnit)
local seb=N.Units[reb.unit_id]
if not(seb and seb.evolve and seb.evolve.evolve_unit)then
ab.pickDone(Zie[3093],Zie[3087],V.name(reb.unit_id)..Zie[3096],Zie[3095])
end
return
end
ab.pickNote.autoEvolve=nil
if not oeb.ready and ab.evolveBuy(oeb)then
for teb,ueb in ipairs(P.goals or{})do
if ueb.pinned and ueb.uuid==O.evolveUnit then
oeb=ueb
break
end
end
end
if not oeb.ready then
return
end
local veb={}
for web,xeb in ipairs(V.equipped())do
veb[xeb.uuid]=true
end
local yeb=ab.evoEats(oeb,veb)
if yeb then
ab.pickNote.autoEvolve=yeb
return
end
if(ab.evoBlocked[oeb.uuid]or 0)>=os.time()then
return
end
local zeb,Aeb=ab.evolve(oeb,Zie[3097])
if zeb then
ab.pickDone(Zie[3093],Zie[3087],Aeb)
else
ab.evoBlocked[oeb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=Aeb
end
end
function ab.evolveText()
if O.evolveUnit==Zie[908]then
return Zie[3098]
end
local Beb=ab.pickNote.autoEvolve and(Zie[1997]..ab.pickNote.autoEvolve)or Zie[908]
if not O.autoEvolve then
return Zie[3099]..Beb
end
for Ceb,Deb in ipairs(P.goals or{})do
if Deb.pinned and Deb.uuid==O.evolveUnit then
return Deb.text..((W.onlyOn()and not Deb.ready)and(Zie[3100]..W.onlyText()..Zie[3101])or Zie[908])..Beb
end
end
return Zie[3102]..Beb
end
ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(Eeb)
local Feb=N.session()
local Geb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local Heb={[Eeb.uuid]=true,[O.evolveUnit]=true}
for Ieb,Jeb in ipairs(V.equipped())do
Heb[Jeb.uuid]=true
end
for Keb,Leb in ipairs(P.savedTeam or{})do
Heb[Leb]=true
end
for Meb,Neb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Heb[Neb]=true
end
local Oeb,Peb={},0
for Qeb,Reb in pairs(Feb.profile_data.collection.owned_units)do
local Seb=N.Units[Reb.unit_id]
local Teb=Seb and ab.FUSE_RANK[Seb.rarity]
if Teb and Teb<=Geb and not Heb[Qeb]then
local Ueb=Feb.collection:get_unit_by_uuid(Qeb)or Reb
if not(Reb._locked or Ueb._locked)and not(Reb._equipped_relic or Ueb._equipped_relic)then
local Veb,Web=pcall(N.USC.calculate_xp_gain_from_fuse,Eeb,{Ueb},Feb)
Web=Veb and tonumber(Web)or 0
if Web>0 then
table.insert(Oeb,{uuid=Qeb,id=Reb.unit_id,xp=Web,rarity=Seb.rarity})
Peb=Peb+Web
end
end
end
end
table.sort(Oeb,function(Xeb,Yeb)
if Xeb.xp~=Yeb.xp then
return Xeb.xp<Yeb.xp
end
return Xeb.uuid<Yeb.uuid
end)
local Zeb=math.max(0,kb.xpFor(Eeb.unit_id,kb.cap(Eeb))-(tonumber(Eeb.xp)or 0))
local _eb,afb={},0
for bfb,cfb in ipairs(Oeb)do
if afb>=Zeb then
break
end
table.insert(_eb,cfb)
afb=afb+cfb.xp
end
return _eb,afb,Zeb,Peb
end
function ab.fuseXpTarget(dfb)
local efb=dfb and dfb.collection:get_unit_by_uuid(O.fuseXpUnit)
if efb then
if O.fuseXpId~=efb.unit_id then
O.fuseXpId=efb.unit_id
F.saveSoon()
end
return efb
end
local ffb=dfb and N.Units[O.fuseXpId]
local gfb=ffb and ffb.evolve and ffb.evolve.evolve_unit
local hfb,ifb
for jfb,kfb in pairs(gfb and dfb.profile_data.collection.owned_units or{})do
if kfb.unit_id==gfb and(not hfb or(tonumber(kfb.xp)or 0)>ifb)then
hfb,ifb=jfb,tonumber(kfb.xp)or 0
end
end
if not hfb then
return nil
end
F.log(1,Zie[2491],string.format(Zie[3103],V.name(O.fuseXpId),V.name(gfb)))
O.fuseXpUnit,O.fuseXpId=hfb,gfb
F.saveSoon()
return dfb.collection:get_unit_by_uuid(hfb)
end
function ab.fuseXpText()
if O.fuseXpUnit==Zie[908]then
return Zie[3104]
end
local lfb=N.session()
local mfb=ab.fuseXpTarget(lfb)
if not mfb then
return Zie[3105]
end
local nfb,ofb,pfb=ab.xpFodder(mfb)
local qfb={}
for rfb,sfb in ipairs(nfb)do
qfb[sfb.rarity]=(qfb[sfb.rarity]or 0)+1
end
local tfb={}
for ufb,vfb in ipairs({Zie[3106],Zie[915],Zie[2557]})do
if qfb[vfb]then
table.insert(tfb,qfb[vfb]..Zie[2208]..vfb)
end
end
local wfb,xfb=kb.level(mfb),kb.cap(mfb)
local yfb
if pfb<=0 then
yfb=string.format(Zie[3107],V.name(mfb.unit_id),wfb,xfb)
elseif#nfb==0 then
yfb=string.format(Zie[3108],V.name(mfb.unit_id),wfb,xfb)
else
yfb=string.format(Zie[3109],V.name(mfb.unit_id),wfb,xfb,table.concat(tfb,Zie[2099]),U.fmt(ofb),kb.level({unit_id=mfb.unit_id,xp=(tonumber(mfb.xp)or 0)+math.min(ofb,pfb)}))
end
yfb=yfb..Zie[3110]..tostring(O.fuseXpRarity)..Zie[3111]
return yfb..(ab.pickNote.autoFuseXp and(Zie[1997]..ab.pickNote.autoFuseXp)or Zie[908])
end
function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==Zie[908]then
return
end
local zfb=N.session()
local Afb=ab.fuseXpTarget(zfb)
if not Afb then
return
end
local Bfb=V.name(Afb.unit_id)
local Cfb,Dfb,Efb=ab.xpFodder(Afb)
if Efb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#Cfb==0 then
ab.pickNote.autoFuseXp=Zie[3112]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=Zie[3113]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local Ffb,Gfb,Hfb=0,0,{}
while F.alive and Ffb<10 and not P.pauseAll do
if Ffb>0 then
local Ifb,Jfb,Kfb=ab.xpFodder(zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb)
Cfb,Efb={},Kfb
for Lfb,Mfb in ipairs(Ifb)do
if not Hfb[Mfb.uuid]then
table.insert(Cfb,Mfb)
end
end
if Efb<=0 or#Cfb==0 then
break
end
end
local Nfb={}
for Ofb=1,math.min(ab.fuseBatch,#Cfb)do
table.insert(Nfb,Cfb[Ofb].uuid)
end
local Pfb=tonumber((zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb).xp)or 0
local Qfb=U.now()
local Rfb,Sfb=F.request(Zie[3114],Zie[3115],O.fuseXpUnit,Nfb)
if not Rfb and(Sfb==Zie[2061]or Sfb==Zie[2060])then
if Sfb==Zie[2060]or Gfb>=3 then
break
end
Gfb=Gfb+1
task.wait(3.5)
continue
end
while U.now()-Qfb<5 and(tonumber((zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb).xp)or 0)<=Pfb do
task.wait(0.1)
end
local Tfb=tonumber((zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb).xp)or 0
if Tfb>Pfb then
Ffb=Ffb+1
for Ufb,Vfb in ipairs(Nfb)do
Hfb[Vfb]=true
end
cb.add(string.format(Zie[3116],#Nfb,Bfb),#Nfb,Zie[3117],string.format(Zie[3118],U.fmt(Tfb-Pfb)))
F.log(1,Zie[2491],string.format(Zie[3119],#Nfb,Bfb,U.fmt(Tfb-Pfb),kb.level(zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb)))
elseif#Nfb>20 then
ab.fuseBatch=20
F.log(1,Zie[2491],string.format(Zie[3120],#Nfb,tostring(F.gameSaid(Qfb)or(Rfb and Sfb)or Zie[2521])))
else
local Wfb=F.gameSaid(Qfb)
ab.pickNote.autoFuseXp=Zie[3121]..tostring(Wfb or(Rfb and Sfb)or Zie[2521])..Zie[3122]
F.log(1,Zie[2491],Zie[3123]..tostring(Wfb or(Rfb and Sfb)or Zie[2521]))
F.backoff(Zie[3114],1800)
break
end
end
end
