function ab.smartEvolve()
if not O.smartEvolve then
return F.status(Zie[3162],Zie[3163])
end
local tgb=N.session()
if not tgb then
return
end
local ugb={}
for vgb,wgb in ipairs(P.goals or{})do
table.insert(ugb,wgb)
end
table.sort(ugb,function(xgb,ygb)
return(xgb.gain or 0)>(ygb.gain or 0)
end)
local zgb={}
for Agb,Bgb in ipairs(V.equipped())do
zgb[Bgb.uuid]=true
end
local Cgb,Dgb,Egb={},0,{}
for Fgb,Ggb in ipairs(ugb)do
if Ggb.pinned then
for Hgb,Igb in ipairs(Ggb.items or{})do
Cgb[Igb.id]=(Cgb[Igb.id]or 0)+Igb.amount
end
end
end
for Jgb,Kgb in ipairs(ugb)do
local Lgb,Mgb
if Kgb.ready and not Kgb.pinned and Dgb<2 and(ab.evoBlocked[Kgb.uuid]or 0)<os.time()then
if Kgb.hidden and(Kgb.tierRank or 0)<hb.TIER_RANK.S then
Lgb=Zie[3164]
end
for Ngb,Ogb in ipairs(Lgb and{}or Kgb.items or{})do
if hb.have(Ogb.id)-Ogb.amount<(Cgb[Ogb.id]or 0)then
Lgb=string.format(Zie[3165],(N.Items[Ogb.id]or{}).name or Ogb.id)
break
end
end
Lgb=Lgb or ab.evoEats(Kgb,zgb)
if not Lgb then
local Pgb,Qgb=ab.evolve(Kgb,Zie[3166]..(#(Kgb.eats or{})>0 and Zie[3167]or Zie[908]))
if Pgb then
Dgb,Mgb=Dgb+1,true
table.insert(Egb,Zie[3073]..V.name(Kgb.from)..Zie[3168]..V.name(Kgb.to))
else
ab.evoBlocked[Kgb.uuid]=os.time()+3600
Lgb=Qgb
end
end
if Lgb then
table.insert(Egb,V.name(Kgb.from)..Zie[2329]..Lgb)
end
end
if not Mgb then
for Rgb,Sgb in ipairs(Kgb.items or{})do
Cgb[Sgb.id]=(Cgb[Sgb.id]or 0)+Sgb.amount
end
end
end
F.status(Zie[3162],#Egb>0 and table.concat(Egb,Zie[2362])or Zie[3169])
end
ib.BONUS=1.5
ib.SLOW=1.4
function ib.boost(Tgb,Ugb,Vgb,Wgb)
if Ugb<2 or Vgb>=math.min(O.dangerReach,(Wgb or 1)*0.9)then
return
end
local Xgb=Vgb<math.min(O.safeReach,(Wgb or 1)*0.75)
local Ygb=0
for Zgb,_gb in ipairs(Tgb)do
if not _gb.farm and not _gb.train and _gb.cost>0 then
Ygb=math.max(Ygb,_gb.gain/_gb.cost)
end
end
for ahb,bhb in ipairs(Tgb)do
if bhb.train==Zie[3170]or(bhb.train==Zie[3171]and Xgb)then
bhb.gain=math.max(bhb.gain,Ygb*bhb.cost*1.05)
end
end
end
ib.HOLD_REACH=0.3
ib.ZONE=0.25
function ib.hold(chb,dhb,ehb)
if dhb<2 or chb>=ib.HOLD_REACH+(ehb and 0.1 or 0)then
return false
end
return true,string.format(Zie[3172],math.floor(chb*100+0.5))
end
function ib.same(fhb,ghb)
if#fhb~= #ghb then
return false
end
local hhb={}
for ihb,jhb in ipairs(fhb)do
hhb[jhb]=true
end
for khb,lhb in ipairs(ghb)do
if not hhb[lhb]then
return false
end
end
return true
end
function ib.team()
local mhb={}
for nhb,ohb in ipairs(V.equipped())do
table.insert(mhb,ohb.uuid)
end
return mhb
end
function ib.target()
local phb=N.session()
if not phb then
return nil
end
local qhb,rhb
local shb=O.autoEvolve and O.evolveUnit~=Zie[908]and O.evolveUnit or nil
for thb,uhb in ipairs(P.goals or{})do
local vhb,whb=nil,0
for xhb,yhb in ipairs(uhb.plans or{})do
if yhb.takedown then
vhb=yhb
else
whb=whb+1
end
end
local zhb=vhb and uhb.intoTeam and(uhb.pinned or not uhb.unknown)and(not shb or uhb.uuid==shb)and phb.collection:get_unit_by_uuid(uhb.uuid)
if zhb then
local Ahb=tonumber(vhb.what==Zie[2638]and zhb.total_kills or zhb.total_takedowns)or 0
if Ahb<vhb.need then
local Bhb=(whb==0 and 1000 or 0)+(tonumber(uhb.tierRank)or 0)*10-thb*0.01
if not qhb or Bhb>rhb then
qhb,rhb={uuid=uhb.uuid,id=uhb.from,to=uhb.to,what=vhb.what,have=Ahb,need=vhb.need},Bhb
end
end
end
end
return qhb
end
function ib.realHave(Chb)
local Dhb=N.session()
local Ehb=Dhb and Dhb.collection:get_unit_by_uuid(Chb.uuid)
local Fhb=Ehb and tonumber(Chb.what==Zie[2638]and Ehb.total_kills or Ehb.total_takedowns)or 0
return math.max(Fhb,Chb.have+(Chb.got or 0))
end
function ib.now()
if ib._at and U.now()-ib._at<10 then
return ib._t,ib._base
end
local Ghb=(P.train.on and P.train.on.base)or ib.team()
local Hhb=table.clone(Ghb)
table.sort(Hhb)
ib._t,ib._base,ib._at=ib.target(),table.concat(Hhb,Zie[2845]),U.now()
return ib._t,ib._base
end
function ib.valueFor(Ihb)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local Jhb=P.trainSim[Ihb.key]
if not(Jhb and Jhb.ok and os.time()-(Jhb.at or 0)<6*3600)then
return 0,1
end
local Khb,Lhb=ib.now()
local Mhb={}
for Nhb,Ohb in ipairs(P.savedTeam or{})do
Mhb[Nhb]=Ohb
end
table.sort(Mhb)
if not(Khb and Jhb.uuid==Khb.uuid and(Jhb.base==Lhb or Jhb.base==table.concat(Mhb,Zie[2845])))or not ib.eligible(Ihb)then
