local mBb=(kBb.cd>0 and kBb.damage/kBb.cd or 0)
local nBb=(lBb.cd>0 and lBb.damage/lBb.cd or 0)*V.aoe(lBb.atk,lBb.range)/math.max(0.3,V.aoe(kBb.atk,kBb.range))
