local pBb=fBb[gBb+2]
if pBb and gBb+1<fBb.max and pBb.cd>0 and lBb.cd>0 and mBb>0 then
local qBb=eBb*((pBb.damage/pBb.cd)/mBb-1)
local rBb=hBb+pBb.cost*iBb
if qBb/rBb>oBb/hBb then
oBb=oBb+(qBb/rBb*hBb-oBb)*0.5
end
end
local sBb=(lBb.range or 0)>(kBb.range or 0)and(1+((lBb.range-kBb.range)/math.max(1,kBb.range)))or 1
return math.max(0,oBb)*sBb
end
function eb.dpsFor(tBb,uBb)
if uBb<=0 then
return 0
end
local vBb={}
for wBb,xBb in ipairs(tBb)do
if not xBb.farm and xBb.gain>0 then
table.insert(vBb,xBb)
end
end
table.sort(vBb,function(yBb,zBb)
return yBb.gain/yBb.cost>zBb.gain/zBb.cost
end)
local ABb,BBb=0,0
for CBb,DBb in ipairs(vBb)do
if uBb<=0 then
break
end
BBb=DBb.gain/DBb.cost
local EBb=math.min(1,uBb/DBb.cost)
ABb=ABb+DBb.gain*EBb
uBb=uBb-DBb.cost*EBb
end
return ABb+math.max(0,uBb)*BBb*0.7
end
function eb.shieldDps(FBb,GBb,HBb,IBb,JBb,KBb,LBb)
if(IBb or 0)<=0 or(FBb or 0)<=0 or(JBb or 0)<=0 then
return FBb or 0
end
GBb,HBb,KBb=math.max(0.3,GBb or 2),math.max(1,HBb or 1),KBb or 1
local MBb=FBb*KBb*GBb/HBb
return JBb*HBb/((IBb/math.max(1,LBb or 1)+math.max(1,JBb/MBb))*GBb)/KBb
end
function eb.shieldGain(NBb,OBb,PBb,QBb,RBb,SBb,TBb,UBb)
local VBb,WBb=V.attackInfo(OBb.atk,OBb.range),V.attackInfo(QBb.atk,QBb.range)
local XBb=eb.shieldDps(NBb,(tonumber(OBb.cd)or 2)*(TBb or 1),VBb.n,RBb,SBb,UBb,VBb.hits)
local YBb=eb.shieldDps(PBb,(tonumber(QBb.cd)or 2)*(TBb or 1),WBb.n,RBb,SBb,UBb,WBb.hits)
local ZBb=math.max(0,((tonumber(QBb.range)or 0)-(tonumber(OBb.range)or 0))/math.max(1,tonumber(OBb.range)or 1))
return math.max(0,YBb-XBb)+XBb*ZBb
end
function eb.shieldWork(_Bb,aCb,bCb,cCb,dCb,eCb,fCb,gCb,hCb)
if(cCb or 0)<=0 then
return 0
end
local iCb=3*cCb*(dCb or 1)/math.max(1,eCb or 20)
