local gPb=P.maps[ePb]or P.maps[tostring(ePb):match(Zie[2422])or Zie[908]]
local hPb=not(gPb and gPb.hill==false)
for iPb,jPb in ipairs(dPb)do
local kPb=N.Units[jPb.unit_id]
local lPb=kPb and V.rows(jPb.unit_id)
if lPb then
table.insert(fPb,{u=jPb,id=jPb.unit_id,data=kPb,rows=lPb,cap=V.cap(jPb),farm=V.isFarm(jPb.unit_id),placeable=(not kPb.hill_unit)or hPb})
end
end
return fPb
end
gb.UNIT_SPLIT,gb.UNIT_MIN,gb.UNIT_MAX,gb.UNIT_SHARE_MIN=0.5,0.2,5,0.02
function gb.unitK(mPb,nPb,oPb)
local pPb=oPb and Zie[3682]or Zie[3683]
local qPb=mPb[pPb]
if not qPb then
qPb={}
mPb[pPb]=qPb
end
local rPb=qPb[nPb.id]
if rPb==nil then
local sPb=oPb and type(mPb.unitKBox)==Zie[1987]and mPb.unitKBox[nPb.id]or nil
if not(type(sPb)==Zie[1987]and tonumber(sPb.k))then
sPb=type(mPb.unitK)==Zie[1987]and mPb.unitK[nPb.id]or nil
end
rPb=(type(sPb)==Zie[1987]and tonumber(sPb.k)and gb.ukNow(sPb,nPb.id))or(not mPb.fbVoid and gb.unitHive(mPb.key,nPb.id))or 1
qPb[nPb.id]=rPb
end
return rPb
end
function gb.ukNow(tPb,uPb)
local vPb,wPb=tonumber(tPb.k)or 1,tonumber(tPb.nu)
if not wPb or wPb<=0 then
return vPb
end
return U.clamp(vPb*wPb/math.max(0.01,V.nudge(uPb)),gb.UNIT_MIN,gb.UNIT_MAX)
end
function gb.unitHive(xPb,yPb)
local zPb,APb=pcall(db.hive)
for BPb,CPb in ipairs({Zie[3684],Zie[3685]})do
local DPb=zPb and APb and type(APb[CPb])==Zie[1987]and APb[CPb][tostring(xPb)]or nil
local EPb=type(DPb)==Zie[1987]and DPb[yPb]or nil
if type(EPb)==Zie[1987]and tonumber(EPb[1])and(tonumber(EPb[2])or 0)>=2 then
return U.clamp(tonumber(EPb[1])*(CPb==Zie[3685]and V.footK(yPb)or 1),gb.UNIT_MIN,gb.UNIT_MAX)
end
end
return nil
end
function gb.footMove()
local FPb=tonumber(P.footV)or 0
if FPb>=2 then
return
end
if FPb<1 then
gb.footMove1()
end
local GPb,HPb=0,{}
for IPb,JPb in pairs(P.simCal or{})do
for KPb,LPb in ipairs({Zie[3686],Zie[3687]})do
for MPb,NPb in pairs(type(JPb)==Zie[1987]and type(JPb[LPb])==Zie[1987]and JPb[LPb]or{})do
local OPb=V.DRONES[MPb]
if type(NPb)==Zie[1987]and tonumber(NPb.k)and OPb and tonumber(OPb.moveK)then
NPb.nu=(tonumber(NPb.nu)or V.nudge(MPb))/OPb.moveK
GPb=GPb+1
HPb[MPb]=true
end
end
end
end
P.footV=2
if GPb>0 then
local PPb={}
for QPb in pairs(HPb)do
table.insert(PPb,string.format(Zie[3688],V.name(QPb),V.DRONES[QPb].moveK))
end
F.log(1,Zie[2097],string.format(Zie[3689],table.concat(PPb,Zie[2099]),GPb))
end
F.saveSoon()
end
function gb.footMove1()
local RPb={}
local function SPb(TPb)
if RPb[TPb]==nil then
local UPb,VPb=0,0
local WPb=P.learn[TPb]
if WPb and tonumber(WPb.n)and WPb.n>=1 then
local XPb=tonumber(WPb.eff)or 1
if(tonumber(WPb.v)or 0)<3 then
XPb=XPb*V.effRescale(TPb)
end
if(tonumber(WPb.v)or 0)<4 then
XPb=XPb*V.secRescale(TPb)
end
UPb,VPb=math.log(math.max(0.01,XPb))*WPb.n,WPb.n
end
local YPb,ZPb=V.hiveEff(TPb,true)
if YPb then
UPb,VPb=UPb+math.log(math.max(0.01,YPb))*ZPb,VPb+ZPb
end
RPb[TPb]=V.nudgeFrom(UPb,VPb)
end
return RPb[TPb]
end
local _Pb=0
for aQb,bQb in pairs(P.simCal or{})do
for cQb,dQb in ipairs({Zie[3686],Zie[3687]})do
for eQb,fQb in pairs(type(bQb)==Zie[1987]and type(bQb[dQb])==Zie[1987]and bQb[dQb]or{})do
if type(fQb)==Zie[1987]and tonumber(fQb.k)and not tonumber(fQb.nu)then
fQb.nu=SPb(eQb)
_Pb=_Pb+1
end
end
end
end
for gQb in pairs(P.learn or{})do
SPb(gQb)
end
for hQb,iQb in pairs(P.learn or{})do
if type(iQb)==Zie[1987]then
V.learnUp(hQb,iQb)
end
end
P.footV=1
local jQb={}
for kQb,lQb in pairs(RPb)do
local mQb=V.nudge(kQb)
if math.abs(mQb/lQb-1)>=0.05 then
table.insert(jQb,{d=math.abs(math.log(mQb/lQb)),t=string.format(Zie[3690],V.name(kQb),lQb,mQb)})
end
end
table.sort(jQb,function(nQb,oQb)
return nQb.d>oQb.d
end)
local pQb={}
for qQb,rQb in ipairs(jQb)do
if qQb<=8 then
table.insert(pQb,rQb.t)
end
end
F.log(1,Zie[2097],string.format(Zie[3691],#pQb>0 and(Zie[2329]..table.concat(pQb,Zie[2362]))or Zie[908],_Pb))
F.saveSoon()
end
function gb.mapK(sQb,tQb)
