gb.GALE_SLOW=0.3
gb.DMG_BANDS={5,10,15,20,30,45,math.huge}
gb.DMG_STEP,gb.DMG_MIN,gb.DMG_MAX,gb.DMG_FLOOR=0.35,0.1,3,1
function gb.dmgBand(PQb)
for QQb,RQb in ipairs(gb.DMG_BANDS)do
if PQb<=RQb then
return QQb
end
end
return#gb.DMG_BANDS
end
function gb.dmgBandName(SQb)
local TQb=gb.DMG_BANDS[SQb]
