gb.DMG_PRIOR_RUNS=6
function gb.dmgAll()
local VQb=gb._dmgAll
if VQb and os.clock()-VQb.t<60 then
return VQb.v
end
local WQb,XQb={},{}
for YQb,ZQb in pairs(P.simCal)do
local _Qb=YQb~=Zie[2013]and not tostring(YQb):find(Zie[3668],1,true)and type(ZQb)==Zie[1987]and type(ZQb.dmgK)==Zie[1987]and ZQb.dmgK or nil
for aRb=1,#gb.DMG_BANDS do
local bRb=_Qb and _Qb[tostring(aRb)]
local cRb,dRb=type(bRb)==Zie[1987]and tonumber(bRb.k)or nil,type(bRb)==Zie[1987]and tonumber(bRb.n)or 0
if cRb and cRb>0 and dRb>0 then
WQb[aRb]=(WQb[aRb]or 0)+dRb*math.log(cRb)
XQb[aRb]=(XQb[aRb]or 0)+dRb
end
end
end
local eRb={}
for fRb,gRb in pairs(WQb)do
eRb[tostring(fRb)]={k=math.exp(gRb/(XQb[fRb]+gb.DMG_PRIOR_RUNS)),n=0}
end
gb._dmgAll={t=os.clock(),v=eRb}
return eRb
end
function gb.dmgHive(hRb)
local iRb,jRb=pcall(db.hive)
local kRb=iRb and jRb and type(jRb.dmg)==Zie[1987]and jRb.dmg[tostring(hRb)]or nil
if type(kRb)~=Zie[1987]then
return nil
end
local lRb={}
for mRb,nRb in pairs(kRb)do
if type(nRb)==Zie[1987]and tonumber(nRb[1])and((tonumber(nRb[2])or 0)>=2 or(tonumber(nRb[3])or 0)>=4)then
lRb[tostring(mRb)]={k=U.clamp(tonumber(nRb[1]),gb.DMG_MIN,gb.DMG_MAX),n=0,hive=true}
end
end
return next(lRb)and lRb or nil
end
function gb.dmgK(oRb,pRb)
local qRb=oRb._dk
if not qRb then
qRb={}
oRb._dk=qRb
end
local rRb=qRb[pRb]
if rRb then
return rRb
end
rRb=1
local sRb=oRb.dmgK
if type(sRb)~=Zie[1987]or next(sRb)==nil then
sRb=(not oRb.fbVoid and gb.dmgHive(oRb.key))or gb.dmgAll()
end
if type(sRb)==Zie[1987]then
local tRb,uRb=gb.dmgBand(math.max(1,pRb)),math.huge
for vRb=1,#gb.DMG_BANDS do
local wRb=sRb[tostring(vRb)]
local xRb=type(wRb)==Zie[1987]and tonumber(wRb.k)or nil
if xRb and math.abs(vRb-tRb)<uRb then
rRb,uRb=xRb,math.abs(vRb-tRb)
end
end
end
rRb=rRb*(tonumber(oRb.dmgMul)or 1)
qRb[pRb]=rRb
return rRb
end
gb.DMG_SOLVE_LO,gb.DMG_SOLVE_HI,gb.DMG_SOLVE_TRIES=0.1,3,6
function gb.dmgSolve(yRb,zRb,ARb,BRb,CRb)
local function DRb(ERb)
local FRb=table.clone(yRb)
FRb.dmgMul,FRb._dk=ERb,nil
local GRb,HRb=pcall(gb.runRaw,FRb,zRb,ARb)
if not(GRb and type(HRb)==Zie[1987])then
return nil
end
if CRb then
return HRb.won and 1 or-1
end
if HRb.won then
return 1
end
return(tonumber(HRb.wave)or 0)-BRb
end
local IRb,JRb=math.log(gb.DMG_SOLVE_LO),math.log(gb.DMG_SOLVE_HI)
local KRb=DRb(gb.DMG_SOLVE_LO)
if not KRb then
return nil
end
if KRb>=0 then
return gb.DMG_SOLVE_LO
end
local LRb=DRb(gb.DMG_SOLVE_HI)
if not LRb then
return nil
end
if LRb<0 then
return gb.DMG_SOLVE_HI
end
for MRb=1,gb.DMG_SOLVE_TRIES do
task.wait()
local NRb=(IRb+JRb)/2
local ORb=DRb(math.exp(NRb))
if not ORb then
return nil
end
if ORb>=0 then
JRb=NRb
else
IRb=NRb
end
end
return math.exp(JRb)
end
function gb.mid(PRb)
