for mSb=6,_Rb do
local nSb,oSb=dSb(aSb,mSb)or 0,dSb(bSb,mSb)or 0
local pSb=0
for qSb,rSb in ipairs((gb.wave(WRb,mSb)))do
pSb=pSb+(tonumber(rSb.hp)or 0)+(tonumber(rSb.bar)or 0)
end
if pSb>0 and math.max(nSb,oSb)>gb.DMG_FLOOR*pSb then
lSb=gb.dmgBand(mSb)
break
end
end
local function sSb(tSb)
local uSb=iSb[tostring(tSb)]
if type(uSb)==Zie[1987]and(tonumber(uSb.n)or 0)>0 then
return tonumber(uSb.n)
end
local vSb,wSb=0,math.huge
for xSb=1,#gb.DMG_BANDS do
local ySb=iSb[tostring(xSb)]
if type(ySb)==Zie[1987]and tonumber(ySb.k)and(tonumber(ySb.n)or 0)>0 and math.abs(xSb-tSb)<wSb then
vSb,wSb=tonumber(ySb.n),math.abs(xSb-tSb)
end
