end
local zSb=gb.dmgBand(math.max(1,_Rb))
local ASb={}
for BSb=1,zSb do
ASb[BSb]=sSb(BSb)
end
local CSb={}
local DSb=ZRb^(1-gb.UNIT_SPLIT)
for ESb=1,zSb do
local FSb=ESb==1 and 1 or gb.DMG_BANDS[ESb-1]+1
local GSb=type(iSb[tostring(ESb)])==Zie[1987]and iSb[tostring(ESb)]or nil
local HSb=(GSb and tonumber(GSb.k))or gb.dmgK(WRb,FSb)
local ISb=ASb[ESb]
if ESb<lSb then
if not GSb then
iSb[tostring(ESb)]={k=HSb,n=0,at=os.time(),src=Zie[3693]}
end
else
local JSb=ISb==0 and 1 or math.max(0.5,1/(ISb+1))
local KSb=U.clamp(HSb*DSb^JSb,gb.DMG_MIN,gb.DMG_MAX)
iSb[tostring(ESb)]={k=KSb,n=ISb+1,at=os.time(),src=Zie[2014]}
table.insert(CSb,string.format(Zie[3694],gb.dmgBandName(ESb),KSb,HSb))
end
end
local LSb=table.clone(WRb)
LSb.dmgMul,LSb._dk=ZRb,nil
local MSb={}
for NSb,OSb in pairs(YRb or{})do
MSb[NSb]=OSb
end
MSb.dealt={}
local PSb=pcall(gb.runRaw,LSb,XRb,MSb)
local QSb={}
for RSb,SSb in pairs(type(gSb[hSb])==Zie[1987]and gSb[hSb]or{})do
QSb[RSb]=SSb
