if PSb then
local TSb,USb={},0
for VSb,WSb in ipairs(XRb)do
if not WSb.farm and not TSb[WSb.id]then
local XSb=(tonumber(MSb.dealt[V.name(WSb.id)])or 0)+(tonumber(MSb.dealt[Zie[2553]..WSb.id])or 0)
