gb.SHARE_FLOOR,gb.SHARE_STEP=0.03,0.5
function gb.shareLearn()
if bb.withOthers or bb.joinedMid or bb.random or bb.trialId or bb.stopping or#game:GetService(Zie[887]):GetPlayers()>1 then
return
end
local nTb=bb.info
if type(nTb)~=Zie[1987]or type(bb.predUnits)~=Zie[1987]or#bb.predUnits==0 or not bb.key then
return
end
local oTb=bb.damageShares()
if not oTb then
return
end
local pTb=gb.teamFrom(bb.predUnits,nTb.map)
local qTb={}
for rTb,sTb in pairs(bb.predOpt or{hpMul=1})do
qTb[rTb]=sTb
end
qTb.dealt={}
if not pcall(gb.runRaw,nTb,pTb,qTb)then
return
end
local tTb,uTb={},0
for vTb,wTb in ipairs(pTb)do
if not wTb.farm and not tTb[wTb.id]then
local xTb=(tonumber(qTb.dealt[V.name(wTb.id)])or 0)+(tonumber(qTb.dealt[Zie[2553]..wTb.id])or 0)
tTb[wTb.id]={e=wTb,d=xTb}
uTb=uTb+xTb
end
end
if uTb<=0 then
return
end
local yTb=gb.cal(bb.key)
local zTb=bb.killZone()and true or false
local ATb=zTb and Zie[3687]or Zie[3686]
local BTb={}
for CTb,DTb in pairs(type(yTb[ATb])==Zie[1987]and yTb[ATb]or{})do
BTb[CTb]=DTb
end
local ETb,FTb=0,0
for GTb,HTb in pairs(tTb)do
HTb.p,HTb.r=HTb.d/uTb,tonumber(oTb[GTb])or 0
if HTb.p>=gb.SHARE_FLOOR or HTb.r>=gb.SHARE_FLOOR then
local ITb=type(BTb[GTb])==Zie[1987]and BTb[GTb]or nil
local JTb=ITb and tonumber(ITb.sn)or 0
HTb.step=U.clamp(gb.SHARE_STEP*math.max(0.5,1/(JTb+1))*math.log((HTb.r+gb.SHARE_FLOOR)/(HTb.p+gb.SHARE_FLOOR)),-math.log(2),math.log(2))
HTb.old,HTb.sn=ITb,JTb
ETb,FTb=ETb+HTb.step,FTb+1
end
end
if FTb<2 then
return
end
local KTb=ETb/FTb
local LTb={}
bb.shareRows={}
for MTb,NTb in pairs(tTb)do
if NTb.step then
bb.shareRows[MTb]={r=NTb.r,p=NTb.p}
end
end
for OTb,PTb in pairs(tTb)do
if PTb.step then
local QTb=(PTb.old and gb.ukNow(PTb.old,OTb))or gb.unitK(nTb,PTb.e,zTb)
local RTb=U.clamp(QTb*math.exp(PTb.step-KTb),gb.UNIT_MIN,gb.UNIT_MAX)
BTb[OTb]={k=RTb,nu=V.nudge(OTb),n=PTb.old and tonumber(PTb.old.n)or 0,sn=PTb.sn+1,at=os.time()}
if math.abs(RTb/QTb-1)>=0.05 then
table.insert(LTb,{p=PTb.p,t=string.format(Zie[3698],V.name(OTb),math.floor(PTb.r*100+0.5),math.floor(PTb.p*100+0.5),RTb,QTb)})
end
end
end
yTb[ATb]=BTb
if#LTb==0 then
return
end
table.sort(LTb,function(STb,TTb)
return STb.p>TTb.p
end)
local UTb={}
for VTb,WTb in ipairs(LTb)do
table.insert(UTb,WTb.t)
end
local XTb,YTb=pcall(bb.label)
F.log(1,Zie[3653],string.format(Zie[3699],tostring(XTb and YTb or bb.key),zTb and Zie[3696]or Zie[3697],table.concat(UTb,Zie[2362])))
