function jb.walletDiff(zjc,Ajc)
local Bjc={}
if Ajc.gems~=zjc.gems then
table.insert(Bjc,string.format(Zie[3931],Ajc.gems-zjc.gems))
end
if Ajc.gold~=zjc.gold then
table.insert(Bjc,string.format(Zie[3932],Ajc.gold-zjc.gold))
end
for Cjc,Djc in pairs(Ajc.items)do
if Djc~=(zjc.items[Cjc]or 0)then
table.insert(Bjc,string.format(Zie[3933],Djc-(zjc.items[Cjc]or 0),tostring(Cjc)))
end
end
for Ejc,Fjc in pairs(Ajc.units)do
if not zjc.units[Ejc]then
table.insert(Bjc,Zie[3934]..V.name(Fjc))
end
end
if Ajc.unique~=zjc.unique then
table.insert(Bjc,string.format(Zie[3935],Ajc.unique-zjc.unique))
end
return#Bjc>0 and table.concat(Bjc,Zie[2099])or Zie[3936]
end
function jb.openChests(Gjc,Hjc)
