if not(Hjc or Mjc>=jb.ROOMS or Ljc<=1)then
jb.note(string.format(Zie[3937],Mjc,Jjc,Kjc,jb.luck(Gjc)))
F.request(Zie[3923],Zie[3924])
return
end
local Njc,Ojc,Pjc=0,0,0
local Qjc=tonumber(N.cur(Zie[2051]))or 0
local Rjc=jb.wallet()
for Sjc=1,Jjc+Kjc+4 do
local Tjc,Ujc,Vjc=jb.res(jb.data())
if Ujc+Vjc<=0 or Pjc>=2 then
break
end
local Wjc,Xjc
if Ujc>0 then
Wjc,Xjc=F.request(Zie[3938],Zie[3939])
else
Wjc,Xjc=F.request(Zie[3938],Zie[3939],true)
end
if Wjc and Xjc~=nil then
F.log(1,Zie[3907],Zie[3940]..(type(Xjc)==Zie[1987]and U.json(U.plain(Xjc)):sub(1,300)or tostring(Xjc)))
end
local Yjc=U.now()
while U.now()-Yjc<4 do
local Zjc,_jc,akc=jb.res(jb.data())
if _jc<Ujc or akc<Vjc then
break
end
task.wait(0.25)
end
local bkc,ckc,dkc=jb.res(jb.data())
if ckc<Ujc then
Njc=Njc+(Ujc-ckc)
Pjc=0
elseif dkc<Vjc then
Ojc=Ojc+(Vjc-dkc)
Pjc=0
else
Pjc=Pjc+1
end
task.wait(1)
if ckc<Ujc or dkc<Vjc then
local ekc=jb.wallet()
local fkc=jb.walletDiff(Rjc,ekc)
F.log(1,Zie[3907],(dkc<Vjc and Zie[3941]or Zie[3940])..fkc)
P.dg.pay=P.dg.pay or{}
local gkc={}
for hkc,ikc in pairs(ekc.items)do
if ikc~=(Rjc.items[hkc]or 0)then
gkc[hkc]=ikc-(Rjc.items[hkc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=dkc<Vjc,gems=ekc.gems-Rjc.gems,luck=jb.luck(Gjc),paid=fkc,items=gkc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Rjc=ekc
end
end
jb.note(string.format(Zie[3942],Njc,Ojc,Hjc and Zie[3943]or(Ljc<=1 and Zie[3944]or Zie[3945]),jb.luck(Gjc),(tonumber(N.cur(Zie[2051]))or 0)-Qjc))
local jkc,kkc,lkc=jb.res(jb.data())
if(Hjc or Mjc>=jb.ROOMS)and kkc+lkc>0 then
jb.note(string.format(Zie[3946],kkc,lkc))
W.rec(Zie[2706]).restUntil=os.time()+1800
return Zie[3947]
end
if not Hjc then
F.request(Zie[3923],Zie[3924])
end
end
