function bb.buildPath()
bb.samples={}
local poc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not poc then
return
end
for qoc,roc in pairs(poc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[qoc.Name])then
local soc={}
for toc,uoc in ipairs(roc.points or{})do
table.insert(soc,uoc.part.Position)
end
local voc=0
for woc=2,#soc do
voc=voc+(soc[woc]-soc[woc-1]).Magnitude
end
local xoc=0
for yoc=2,#soc do
local zoc,Aoc=soc[yoc-1],soc[yoc]
local Boc=(Aoc-zoc).Magnitude
local Coc=math.max(1,math.floor(Boc/2))
for Doc=0,Coc-1 do
local Eoc=zoc:Lerp(Aoc,Doc/Coc)
table.insert(bb.samples,{pos=Eoc,prog=(xoc+Boc*Doc/Coc)/math.max(1,voc),lane=qoc.Name})
end
xoc=xoc+Boc
end
if soc[#soc]then
table.insert(bb.samples,{pos=soc[#soc],prog=1,lane=qoc.Name})
end
end
end
pcall(bb.readHidden,poc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Foc=tonumber(bb.ld and bb.ld._portal_lanes)
local Goc=gb.laneList(bb.samples)
if Foc and Foc>=1 and Goc and#Goc>Foc then
bb.laneWant=Foc
end
bb.laneTotal=Goc and#Goc or 1
bb.countLanes()
