function bb.readHidden(Hoc)
local Ioc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Ioc)~=Zie[1987]or not next(Ioc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Joc
for Koc,Loc in pairs(Hoc)do
if Ioc[Koc.Name]and type(Loc.points)==Zie[1987]and#Loc.points>=2 then
local Moc={}
for Noc,Ooc in ipairs(Loc.points)do
Moc[Noc]=U.flat(Ooc.part.Position)
end
local Poc={}
for Qoc,Roc in ipairs(bb.samples)do
local Soc=tostring(Roc.lane)
Poc[Soc]=Poc[Soc]or{}
table.insert(Poc[Soc],Roc)
end
local Toc,Uoc
for Voc,Woc in pairs(Poc)do
local Xoc=0
for Yoc=1,#Moc,math.max(1,math.floor(#Moc/20))do
local Zoc=math.huge
for _oc,apc in ipairs(Woc)do
local bpc=(U.flat(apc.pos)-Moc[Yoc]).Magnitude
if bpc<Zoc then
Zoc=bpc
end
end
Xoc=Xoc+Zoc
end
if not Uoc or Xoc<Uoc then
Toc,Uoc=Voc,Xoc
end
end
local cpc,dpc,epc,fpc,gpc,hpc={},nil,nil,nil,0,0
for ipc,jpc in ipairs(Moc)do
local kpc,lpc=nil,math.huge
for mpc,npc in ipairs(Poc[Toc])do
local opc=(U.flat(npc.pos)-jpc).Magnitude
if opc<lpc then
lpc,kpc=opc,npc.prog
end
end
hpc=math.max(hpc,lpc)
if epc then
local ppc=kpc-epc
local qpc=(ppc>0.002 and 1)or(ppc< -0.002 and-1)or fpc
if fpc and qpc and qpc~=fpc then
table.insert(cpc,math.floor(epc*1000+0.5)/1000)
end
fpc,gpc=qpc or fpc,gpc+math.abs(ppc)
else
dpc=kpc
end
epc=kpc
if ipc%50==0 then
task.wait()
end
end
if epc and hpc<=8 then
table.insert(cpc,math.floor(epc*1000+0.5)/1000)
Joc=Joc or{}
Joc[Koc.Name]={from=math.floor((dpc or 0)*1000+0.5)/1000,len=math.floor(gpc*1000+0.5)/1000,turns=cpc,road=Toc}
end
end
end
if not Joc then
return
end
local rpc=bb.ld.map
P.maps[rpc]=P.maps[rpc]or{}
local spc=P.maps[rpc].hidden
P.maps[rpc].hidden=Joc
if type(spc)~=Zie[1987]then
for tpc,upc in pairs(Joc)do
F.log(1,Zie[2655],string.format(Zie[4035],tpc,upc.len,tostring(upc.road),math.floor((#upc.turns-1)/2)))
end
F.saveSoon()
end
end
