function bb.valid(Csc,Dsc,Esc)
local Fsc=N.PC.raycast(Csc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Fsc then
return nil
end
if not N.PC.is_valid_raycast_hit(Fsc.Instance,Dsc)then
return nil
end
local Gsc=Fsc.Position
if bb.blockedSpot(Gsc)then
return nil
end
local Hsc=(tonumber(Dsc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Hsc*2,2.5,Hsc*2)
bb.probe.CFrame=CFrame.new(Gsc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Isc=U.flat(Gsc)
for Jsc,Ksc in ipairs(bb.mine or{})do
local Lsc=Ksc:FindFirstChild(Zie[4071])
local Msc=Lsc and Lsc.Position or Ksc:GetPivot().Position
local Nsc=Lsc and math.max(Lsc.Size.X,Lsc.Size.Z)/2 or 1.5
if(Isc-U.flat(Msc)).Magnitude<Hsc+Nsc then
return nil
end
end
if not Esc then
for Osc,Psc in ipairs(bb.blockers())do
if(Isc-Psc.p).Magnitude<Hsc+Psc.r then
return nil
end
end
end
return Gsc
end
function bb.buildCandidates()
bb.cands={}
local Qsc={}
for Rsc=1,#bb.samples,3 do
local Ssc=bb.samples[Rsc]
local Tsc=bb.samples[math.min(#bb.samples,Rsc+1)]
local Usc=U.flat(Tsc.pos-Ssc.pos)
if Usc.Magnitude<0.01 then
Usc=Vector3 .new(1,0,0)
end
Usc=Usc.Unit
local Vsc=Vector3 .new(-Usc.Z,0,Usc.X)
for Wsc,Xsc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Ysc,Zsc in ipairs({1,-1})do
local _sc=Ssc.pos+Vsc*Xsc*Zsc
local atc=string.format(Zie[4068],math.floor(_sc.X/1.5),math.floor(_sc.Z/1.5))
if not Qsc[atc]then
Qsc[atc]=true
table.insert(bb.cands,_sc)
end
end
end
end
end
function bb.coverage(btc,ctc)
local dtc={}
for etc,ftc in ipairs(btc)do
local gtc=ftc._stats
if not V.isFarm(gtc.id.Value)and gtc:FindFirstChild(Zie[2239])then
table.insert(dtc,{p=U.flat(ftc:GetPivot().Position),r=gtc.range.Value*(V.SUMMONER[gtc.id.Value]and V.SUMMONER[gtc.id.Value].reach or 1),air=bb.canAir(ftc)})
end
end
local htc,itc=0,0
if#dtc>0 then
for jtc,ktc in ipairs(bb.samples)do
if ktc.prog>itc then
local ltc=U.flat(ktc.pos)
for mtc,ntc in ipairs(dtc)do
if(ltc-ntc.p).Magnitude<=ntc.r then
if ktc.prog>htc then
htc=ktc.prog
end
if ntc.air then
itc=ktc.prog
break
end
end
end
end
end
end
local otc,ptc={},bb.laneCount
if ptc and ptc.n>=2 and#dtc>0 then
local qtc={}
for rtc,stc in ipairs(bb.samples)do
local ttc=U.flat(stc.pos)
for utc,vtc in ipairs(dtc)do
if(ttc-vtc.p).Magnitude<=vtc.r then
local wtc=tostring(stc.lane)
qtc[wtc]=(qtc[wtc]or 0)+1
if stc.prog>(otc[wtc]or 0)then
otc[wtc]=stc.prog
end
break
end
end
end
local xtc,ytc={},0
for ztc,Atc in pairs(ptc.by)do
xtc[ztc]=(qtc[ztc]or 0)/math.max(1,Atc)
ytc=math.max(ytc,xtc[ztc])
end
bb.laneW={}
for Btc,Ctc in pairs(ptc.by)do
bb.laneW[Btc]=(ptc.avg/math.max(1,Ctc))*(1+1.5*(ytc>0 and(1-xtc[Btc]/ytc)or 0))
end
bb.laneFrac=xtc
else
bb.laneW,bb.laneFrac=nil,nil
end
local Dtc,Etc,Ftc
if#dtc>0 then
for Gtc,Htc in ipairs(ctc)do
local Itc=(bb.laneW and Htc.lane)and(otc[tostring(Htc.lane)]or 0)or htc
if Htc.hp>0 and Htc.prog>Itc+0.02 and Htc.prog>(Dtc or 0)then
Dtc,Ftc=Htc.prog,bb.laneW and Htc.lane or nil
end
if Htc.hp>0 and Htc.fly and Htc.prog>itc+0.02 then
Etc=true
end
end
end
local Jtc= #dtc>0 and(bb.pressure or 0)>=htc-0.08
return{covEnd=htc,airEnd=itc,leak=Dtc,leakLane=Ftc,covL=otc,airLeak=Etc,push=Jtc,units= #dtc}
end
function bb.needLastLine(Ktc)
if V.isFarm(Ktc.id)or V.allyBuff(Ktc.id)or bb.fieldCount()<5 then
return false
end
local Ltc,Mtc=0,0
for Ntc,Otc in ipairs(bb.mine or{})do
local Ptc=Otc._stats
if not V.isFarm(Ptc.id.Value)and Ptc:FindFirstChild(Zie[2239])then
local Qtc,Rtc=U.flat(Otc:GetPivot().Position),Ptc.range.Value
for Stc,Ttc in ipairs(bb.samples)do
if Ttc.prog>=0.85 and(U.flat(Ttc.pos)-Qtc).Magnitude<=Rtc then
Ltc=Ltc+1
if bb.canAir(Otc)then
Mtc=Mtc+1
end
break
end
end
end
end
return Ltc<2 or(Mtc<1 and bb.flyMode()and bb.cardAir(Ktc.id))
end
bb.airCache=setmetatable({},{__mode=Zie[2372]})
function bb.canAir(Utc)
local Vtc=Utc._stats:FindFirstChild(Zie[2078])and Utc._stats.upgrade.Value or 0
local Wtc=bb.airCache[Utc]
if not Wtc or Wtc.lvl~=Vtc then
local Xtc=Utc:GetAttribute(Zie[4073])==true or Utc:GetAttribute(Zie[4074])==true
Wtc={lvl=Vtc,v=Xtc}
bb.airCache[Utc]=Wtc
end
return Wtc.v
end
V._airFrom={}
function V.airFrom(Ytc)
local Ztc=V._airFrom[Ytc]
if Ztc~=nil then
return Ztc or nil
end
local _tc=N.Units[Ytc]
if _tc and(_tc.hill_unit or _tc.hybrid_placement or V.SUMMONER[Ytc])then
V._airFrom[Ytc]=0
return 0
end
local auc=V.rows(Ytc)
if not(auc and auc.max)then
return bb.cardAir(Ytc)and 0 or nil
end
local buc=false
for cuc=0,auc.max do
local duc=auc[cuc]and auc[cuc].atk
if duc and N.Attacks[duc]and N.Attacks[duc].targets_flying then
buc=cuc
break
end
end
if buc==false and bb.cardAir(Ytc)then
buc=0
end
V._airFrom[Ytc]=buc
return buc or nil
end
function bb.cardAir(euc)
local fuc=N.Units[euc]
if not fuc then
return false
end
if fuc.hill_unit or fuc.hybrid_placement then
return true
end
local guc=V.field(euc,Zie[2092])or V.field(euc,Zie[2091])
return guc and N.Attacks[guc]and N.Attacks[guc].targets_flying and true or false
end
function bb.airShare()
local huc,iuc=0,0
for juc,kuc in ipairs(bb.mine or{})do
local luc=kuc._stats.id.Value
if not V.isFarm(luc)then
local muc,nuc=pcall(bb.liveDps,kuc,luc)
nuc=muc and nuc or 0
huc=huc+nuc
if bb.canAir(kuc)then
iuc=iuc+nuc
end
end
end
return huc>0 and iuc/huc or 0
end
