if Quc and Ruc and not Ruc.unsellable and not bb.sandSold[Nuc]and not V.idol(Puc)and Ouc:FindFirstChild(Zie[2239])and type(Quc.types)==Zie[1987]then
local Suc,Tuc=U.flat(Nuc:GetPivot().Position),tonumber(Ouc.range.Value)or 0
local Uuc,Vuc=false,false
