local dvc=cvc and N.Units[cvc]
local evc=bvc and bvc:FindFirstChild(Zie[2363])and bvc.uuid.Value
if dvc and not dvc.unsellable and not bb.sandSold[cvc]and not V.isFarm(cvc)and not V.allyBuff(cvc)and not V.BLESS.by[cvc]and not V.idol(cvc)and bvc:FindFirstChild(Zie[2239])then
local fvc=tonumber(bvc.range.Value)or 0
for gvc,hvc in ipairs(bb.team or{})do
if hvc.uuid==evc and hvc.u and V.rows(cvc)then
