if not jvc then
bb.sandSold[cvc]=true
local mvc=bvc:FindFirstChild(Zie[4077])and tonumber(bvc.total_spent.Value)or 0
local nvc,ovc=F.request(Zie[2169],Zie[2367],avc)
if ovc==true then
F.log(1,Zie[4075],string.format(Zie[4078],V.name(cvc),U.fmt(mvc),math.floor(bb.sandLine()*100+0.5)))
