function bb.cover(pvc,qvc,rvc,tvc,uvc)
local vvc=0
local wvc=U.flat(pvc)
local xvc=rvc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local yvc=bb.laneW
for zvc,Avc in ipairs(uvc and bb.samples or bb.hurtSamples())do
if(U.flat(Avc.pos)-wvc).Magnitude<=qvc then
local Bvc=1
if xvc then
Bvc=0.15+0.85*(tonumber(xvc[math.min(gb.BINS,math.floor(Avc.prog*gb.BINS)+1)])or 0)
end
if yvc then
Bvc=Bvc*(yvc[tostring(Avc.lane)]or 1)
end
if tvc then
if tvc.leak and Avc.prog>=tvc.leak-0.01 and(not tvc.leakLane or tostring(Avc.lane)==tvc.leakLane)then
Bvc=Bvc+3
elseif tvc.push and Avc.prog>tvc.covEnd then
Bvc=Bvc+0.6
end
end
vvc=vvc+Bvc
