for yMc,zMc in ipairs(bb.mine or{})do
local AMc=zMc._stats
local BMc=AMc.id.Value
if AMc:FindFirstChild(Zie[2239])and not V.isFarm(BMc)and not V.allyBuff(BMc)then
local CMc,DMc=U.flat(zMc:GetPivot().Position),AMc.range.Value
if sMc(BMc)and not V.toggleOf(BMc)then
vMc=vMc+1
table.insert(wMc,{p=CMc,r=DMc})
else
for EMc,FMc in ipairs(xMc)do
if(U.flat(FMc.pos)-CMc).Magnitude<=DMc then
tMc,uMc=math.min(tMc,FMc.prog),math.max(uMc,FMc.prog)
end
end
end
end
end
if uMc<=tMc then
tMc,uMc=0.75,0.98
end
local GMc=(rMc or vMc)+1
local HMc=({tMc,uMc,(tMc+uMc)/2,tMc-(uMc-tMc)/2})[GMc]
if not HMc then
return nil
end
local IMc=V.range(qMc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local JMc={}
for KMc,LMc in ipairs(bb.cands)do
local MMc,NMc,OMc=U.flat(LMc),0,0
for PMc,QMc in ipairs(xMc)do
if(U.flat(QMc.pos)-MMc).Magnitude<=IMc then
OMc=OMc+1
if math.abs(QMc.prog-HMc)<=0.05 then
NMc=NMc+1
local RMc=U.flat(QMc.pos)
for SMc,TMc in ipairs(wMc)do
if(RMc-TMc.p).Magnitude<=TMc.r then
NMc=NMc-0.5
break
end
end
end
end
end
if NMc>0 then
table.insert(JMc,{pos=LMc,sc=NMc,cov=OMc})
end
if KMc%60==0 then
task.wait()
end
end
table.sort(JMc,function(UMc,VMc)
return UMc.sc>VMc.sc
end)
for WMc,XMc in ipairs(JMc)do
local YMc=bb.valid(XMc.pos,qMc.data)
if YMc then
F.log(1,Zie[4075],string.format(Zie[4227],V.name(qMc.id),bb.CONTROL_WORDS[GMc],math.floor(HMc*100+0.5)))
return YMc,XMc.cov,HMc
end
if WMc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(ZMc)
