local gNc=fNc.id.Value
if fNc:FindFirstChild(Zie[2239])and not V.isFarm(gNc)and not V.allyBuff(gNc)and gNc~=ZMc.id then
local hNc,iNc=pcall(bb.liveDps,eNc,gNc)
iNc=hNc and tonumber(iNc)or 0
