pcall(bb.sampleHelpers,true)
for kRc,lRc in pairs(bb.ownDealt)do
if lRc.id==bb.trialId then
fRc=fRc+lRc.v
end
end
local mRc=0
for nRc,oRc in pairs(bb.helperDealt)do
if oRc.owner==bb.trialId then
mRc=mRc+oRc.v
end
end
table.insert(bb.trialTrace,string.format(Zie[4242],bRc,aRc-(bb.startT or aRc),cRc,table.concat(eRc,Zie[2845]),gRc,fRc+mRc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[bRc-1]or 0,bb.teamDps or 0))
end
if ZQc.lastW and ZQc.lastW>0 and ZQc.lastWT then
table.insert(ZQc.waveSec,aRc-ZQc.lastWT)
end
if ZQc.paidT and bRc>0 and aRc-ZQc.paidT<15 then
table.insert(ZQc.skip,aRc-ZQc.paidT)
end
ZQc.paidT=nil
if bRc>0 then
ZQc.alive[tostring(bRc)]=bb.hpAliveRaw or 0
end
ZQc.lastW,ZQc.lastWT=bRc,aRc
end
local pRc=workspace:FindFirstChild(Zie[4243])
if pRc and bRc>0 then
ZQc.timer[tostring(bRc)]=math.max(ZQc.timer[tostring(bRc)]or 0,tonumber(pRc.Value)or 0)
end
local qRc=cRc-(bb.lastMoneyR or cRc)
bb.lastMoneyR=cRc
