local ebd,fbd=0,0
local gbd,hbd=_ad.foes or{},abd.foes or{}
for ibd,jbd in pairs(hbd)do
if jbd.prog>=bb.BASE_END then
ebd=ebd+jbd.hp
local kbd=gbd[ibd]
if kbd then
fbd=fbd+math.max(0,kbd.hp-jbd.hp)
end
end
end
for lbd,mbd in pairs(gbd)do
if mbd.prog>=bb.BASE_END and not hbd[lbd]then
